/**
 * FreeWire — Plugin Bridge
 *
 * freelang-ecosystem의 플러그인 시스템과 FreeWire를 연결합니다.
 *
 * 기능:
 *   1. PluginLoader로 freewire-stdlib 플러그인 로드
 *   2. 노드 팔레트에 stdlib 카테고리 추가
 *   3. GraphCompiler가 stdlib 노드 코드 생성에 사용할 codeGenNode() 제공
 *   4. GET /api/nodes 응답에 stdlib 카테고리 포함
 */
'use strict';

const path = require('path');

// freelang-ecosystem 경로 (FreeWire와 같은 레벨에 위치)
const ECOSYSTEM_PATH = path.resolve(__dirname, '../../../../freelang-ecosystem');

let _bridge = null;  // 싱글턴

class PluginBridge {
  constructor() {
    this._ready    = false;
    this._loader   = null;
    this._stdlib   = null;
    this._nodeDefs = [];   // NODE_DEF 배열
    this._codeGenMap = {}; // type → codeGen fn
    this._errors   = [];
  }

  // ── 초기화 ────────────────────────────────────────────────

  /**
   * 플러그인 시스템을 초기화합니다.
   * 서버 시작 시 1회 호출.
   */
  init() {
    if (this._ready) return this;

    try {
      const { PluginLoader }   = require(path.join(ECOSYSTEM_PATH, 'plugin/plugin-loader'));
      const { PluginRegistry } = require(path.join(ECOSYSTEM_PATH, 'plugin/plugin-registry'));
      const stdlib             = require(path.join(ECOSYSTEM_PATH, 'stdlib/index'));
      const freewireStdlib     = require(path.join(ECOSYSTEM_PATH, 'plugins/freewire-stdlib'));

      this._stdlib = stdlib;

      const registry = new PluginRegistry();
      registry.register(freewireStdlib);

      this._loader = new PluginLoader({ registry, stdlib });
      this._loader
        .on('log',    ({ plugin, msg }) => console.log(`[Plugin:${plugin}] ${msg}`))
        .on('warn',   ({ plugin, msg }) => console.warn(`[Plugin:${plugin}] ⚠ ${msg}`))
        .on('loaded', ({ plugin })      => console.log(`[Plugin] ✓ ${plugin} 로드됨`));

      this._loader.load('freewire-stdlib');

      // freewire 확장 추출
      const entry  = this._loader.getLoaded('freewire-stdlib');
      const fw     = entry?.plugin?.provides?.freewire;

      if (fw) {
        this._nodeDefs = fw.nodeDefs || [];
        // codeGenMap 빌드
        for (const def of this._nodeDefs) {
          if (def.codeGen) this._codeGenMap[def.type] = def.codeGen;
        }
        this._paletteCategory = fw.palette;
        this._createNode      = fw.createNode.bind(fw);
      }

      this._ready = true;
      console.log(`[PluginBridge] 초기화 완료 — stdlib 노드 ${this._nodeDefs.length}개`);

    } catch (e) {
      this._errors.push(e.message);
      console.warn(`[PluginBridge] 초기화 실패 (ecosystem 없음): ${e.message}`);
    }

    return this;
  }

  // ── 조회 ──────────────────────────────────────────────────

  get isReady()  { return this._ready; }
  get nodeDefs() { return this._nodeDefs; }
  get errors()   { return this._errors; }

  /**
   * /api/nodes 응답에 포함할 stdlib 팔레트 카테고리 반환
   * @returns {object|null}
   */
  getPaletteCategory() {
    if (!this._ready || !this._paletteCategory) return null;

    return {
      label:  this._paletteCategory.label,
      color:  this._paletteCategory.color,
      icon:   this._paletteCategory.icon,
      subtypes: this._nodeDefs.map(d => ({
        id:    d.type,
        label: d.label,
        color: d.color,
      })),
    };
  }

  /**
   * 주어진 노드가 stdlib 노드인지 확인
   * @param {object} node
   * @returns {boolean}
   */
  isStdlibNode(node) {
    return typeof node?.stdlibFn === 'string' ||
           (typeof node?.type === 'string' && node.type.startsWith('stdlib:'));
  }

  /**
   * stdlib 노드의 .free script 코드 생성
   * @param {object} node — FreeWire 노드 JSON
   * @returns {string}
   */
  codeGenNode(node) {
    if (!this._ready) return `/* PluginBridge not ready */`;

    // stdlibFn 기준으로 type 결정
    const type = node.stdlibFn
      ? `stdlib:${node.stdlibFn}`
      : node.type;

    const codeGen = this._codeGenMap[type];
    if (!codeGen) return `/* stdlib codeGen 없음: ${type} */`;
    return codeGen(node);
  }

  /**
   * stdlib 노드 인스턴스 생성
   * @param {string} type  — 예: 'stdlib:math.clamp'
   * @param {string} id
   * @param {object} opts
   * @returns {object} FreeWire 노드 JSON
   */
  createNode(type, id, opts = {}) {
    if (!this._ready || !this._createNode) {
      throw new Error(`PluginBridge가 초기화되지 않았습니다`);
    }
    return this._createNode(type, id, opts);
  }
}

// ── 싱글턴 ──────────────────────────────────────────────────

function getBridge() {
  if (!_bridge) {
    _bridge = new PluginBridge();
    _bridge.init();
  }
  return _bridge;
}

module.exports = { PluginBridge, getBridge };

