/**
 * FreeWire Phase 15 — Plugin Bridge & StdLib 노드 통합 테스트
 * node src/test/test-phase15.js
 */
'use strict';

let pass = 0, fail = 0;

function test(label, fn) {
  try {
    fn();
    console.log(`  ✓ ${label}`);
    pass++;
  } catch (e) {
    console.error(`  ✗ ${label}: ${e.message}`);
    fail++;
  }
}

function assert(cond, msg = 'assertion failed') {
  if (!cond) throw new Error(msg);
}

// ── 모듈 로드 ────────────────────────────────────────────────
const { getBridge, PluginBridge } = require('../core/plugin-bridge');
const { GraphCompiler }           = require('../compiler/graph-compiler');
const { Graph }                   = require('../core/graph');

// 모의 freewire-stdlib 플러그인 (freelang-ecosystem 없을 때)
const freewireStdlib = {
  name: 'freewire-stdlib',
  version: '0.1.0',
  provides: {
    nodes: [
      { type: 'stdlib/string/concat', label: 'String Concat', inputs: 2, outputs: 1 },
      { type: 'stdlib/string/length', label: 'String Length', inputs: 1, outputs: 1 },
      { type: 'stdlib/array/push', label: 'Array Push', inputs: 2, outputs: 1 },
      { type: 'stdlib/array/map', label: 'Array Map', inputs: 2, outputs: 1 },
      { type: 'stdlib/math/add', label: 'Math Add', inputs: 2, outputs: 1 },
      { type: 'stdlib/math/mul', label: 'Math Mul', inputs: 2, outputs: 1 },
      { type: 'stdlib/json/parse', label: 'JSON Parse', inputs: 1, outputs: 1 },
      { type: 'stdlib/json/stringify', label: 'JSON Stringify', inputs: 1, outputs: 1 },
      { type: 'stdlib/http/get', label: 'HTTP GET', inputs: 1, outputs: 1 },
      { type: 'stdlib/http/post', label: 'HTTP POST', inputs: 2, outputs: 1 }
    ],
    freewire: {
      palette: {
        stdlib: {
          label: 'Standard Library',
          color: '#4CAF50',
          nodes: [
            { type: 'stdlib/string/concat', label: 'Concat' },
            { type: 'stdlib/array/push', label: 'Push' },
            { type: 'stdlib/math/add', label: 'Add' }
          ]
        }
      },
      codegen: {
        'stdlib/string/concat': () => 'const concat = (a, b) => a + b;',
        'stdlib/math/add': () => 'const add = (a, b) => a + b;'
      }
    }
  }
};

// ── freewire-stdlib 플러그인 명세 ────────────────────────────
console.log('\n[freewire-stdlib / 플러그인 명세]');

test('name = freewire-stdlib', () => {
  assert(freewireStdlib.name === 'freewire-stdlib');
});

test('provides.nodes — 10개', () => {
  assert(freewireStdlib.provides.nodes.length === 10);
});

test('provides.nodes — type/label 포함', () => {
  const n = freewireStdlib.provides.nodes[0];
  assert(typeof n.type === 'string' && typeof n.label === 'string');
});

test('provides.freewire — 존재', () => {
  assert(typeof freewireStdlib.provides.freewire === 'object');
});

test('provides.freewire.palette — 4개 그룹', () => {
  assert(freewireStdlib.provides.freewire.palette.groups.length === 4);
});

test('provides.freewire.nodeDefs — 10개', () => {
  assert(freewireStdlib.provides.freewire.nodeDefs.length === 10);
});

// ── createNode ───────────────────────────────────────────────
console.log('\n[freewire-stdlib / createNode]');

const fw = freewireStdlib.provides.freewire;

test('createNode — datetime.now', () => {
  const n = fw.createNode('stdlib:datetime.now', 'n1');
  assert(n.id === 'n1');
  assert(n.type === 'data');
  assert(n.stdlibFn === 'datetime.now');
  assert(n.inputs.length === 0);
  assert(n.outputs.length === 1);
});

test('createNode — math.clamp', () => {
  const n = fw.createNode('stdlib:math.clamp', 'n2', { min: 0, max: 10 });
  assert(n.stdlibFn === 'math.clamp');
  assert(n.inputs.length === 3);
  assert(n.props.min === 0 && n.props.max === 10);
});

test('createNode — string.template', () => {
  const n = fw.createNode('stdlib:string.template', 'n3', { template: 'Hi {name}' });
  assert(n.stdlibFn === 'string.template');
  assert(n.props.template === 'Hi {name}');
});

test('createNode — array.chunk', () => {
  const n = fw.createNode('stdlib:array.chunk', 'n4', { size: 3 });
  assert(n.stdlibFn === 'array.chunk');
  assert(n.props.size === 3);
});

test('createNode — 없는 타입 → throw', () => {
  let threw = false;
  try { fw.createNode('stdlib:unknown.fn', 'nx'); } catch { threw = true; }
  assert(threw);
});

// ── codeGen ──────────────────────────────────────────────────
console.log('\n[freewire-stdlib / codeGen]');

test('codeGen — datetime.now: const 선언 포함', () => {
  const n    = fw.createNode('stdlib:datetime.now', 'abc123');
  const code = fw.codeGenNode(n);
  assert(code.includes('const _stdlib_abc123_date = new Date()'));
  assert(code.includes('stdlib:datetime.now'));
});

test('codeGen — math.clamp: 함수 + 결과 포함', () => {
  const n    = fw.createNode('stdlib:math.clamp', 'x1', { min: 5, max: 95 });
  const code = fw.codeGenNode(n);
  assert(code.includes('Math.min(Math.max'));
  assert(code.includes('_result'));
});

test('codeGen — math.lerp: 3인자 포함', () => {
  const n    = fw.createNode('stdlib:math.lerp', 'x2', { a: 0, b: 100, t: 0.5 });
  const code = fw.codeGenNode(n);
  assert(code.includes('a + (b - a) * t'));
});

test('codeGen — string.template: replace 포함', () => {
  const n    = fw.createNode('stdlib:string.template', 'x3');
  const code = fw.codeGenNode(n);
  assert(code.includes('replace'));
  assert(code.includes('{'));
});

test('codeGen — string.truncate: slice 포함', () => {
  const n    = fw.createNode('stdlib:string.truncate', 'x4', { maxLen: 20 });
  const code = fw.codeGenNode(n);
  assert(code.includes('slice'));
  assert(code.includes('20'));
});

test('codeGen — array.chunk: out.push 포함', () => {
  const n    = fw.createNode('stdlib:array.chunk', 'x5', { size: 3 });
  const code = fw.codeGenNode(n);
  assert(code.includes('out.push'));
  assert(code.includes('3'));
});

test('codeGen — array.groupBy: 결과 객체 포함', () => {
  const n    = fw.createNode('stdlib:array.groupBy', 'x6', { key: 'category' });
  const code = fw.codeGenNode(n);
  assert(code.includes('category'));
  assert(code.includes('push'));
});

// ── PluginBridge ─────────────────────────────────────────────
console.log('\n[PluginBridge]');

const bridge = getBridge();

test('getBridge — 싱글턴', () => {
  assert(getBridge() === bridge);
});

test('bridge.isReady', () => {
  assert(bridge.isReady);
});

test('bridge.nodeDefs.length === 10', () => {
  assert(bridge.nodeDefs.length === 10);
});

test('isStdlibNode — stdlibFn 있으면 true', () => {
  const n = fw.createNode('stdlib:datetime.now', 'n_test');
  assert(bridge.isStdlibNode(n));
});

test('isStdlibNode — 일반 노드 false', () => {
  assert(!bridge.isStdlibNode({ id: 'x', type: 'data', dataType: 'string' }));
});

test('bridge.codeGenNode — 정상 생성', () => {
  const n    = fw.createNode('stdlib:math.round', 'r1', { decimals: 2 });
  const code = bridge.codeGenNode(n);
  assert(code.length > 0 && code.includes('_stdlib_r1'));
});

test('getPaletteCategory — stdlib 카테고리 반환', () => {
  const cat = bridge.getPaletteCategory();
  assert(cat !== null);
  assert(cat.label === 'StdLib 함수');
  assert(Array.isArray(cat.subtypes));
  assert(cat.subtypes.length === 10);
});

test('createNode — bridge를 통해 생성', () => {
  const n = bridge.createNode('stdlib:datetime.diffDays', 'dd1');
  assert(n.stdlibFn === 'datetime.diffDays');
  assert(n.inputs.length === 2);
});

// ── GraphCompiler 연동 ───────────────────────────────────────
console.log('\n[GraphCompiler / stdlib 노드 컴파일]');

function buildGraph(stdlibNodeType, extraProps = {}) {
  // stdlib 노드 1개 + 표시용 component 1개를 가진 최소 그래프
  const stdNode = bridge.createNode(stdlibNodeType, 'sn1', extraProps);
  const compNode = {
    id: 'c1', type: 'component', componentType: 'text',
    inputs: [], outputs: [],
    props: { name: 'TestComp', label: '테스트', text: 'hello' },
    meta: { freelangBlock: 'markup', position: { x: 0, y: 0 } },
  };
  return { id: 'test-graph', nodes: [stdNode, compNode], edges: [] };
}

test('datetime.now 노드 컴파일', () => {
  const compiler = new GraphCompiler();
  const { code, errors } = compiler.compile(buildGraph('stdlib:datetime.now'));
  assert(errors.length === 0, errors.join(', '));
  assert(code.includes('new Date()'));
  assert(code.includes('stdlib:datetime.now'));
});

test('math.clamp 노드 컴파일', () => {
  const compiler = new GraphCompiler();
  const { code, errors } = compiler.compile(
    buildGraph('stdlib:math.clamp', { min: 0, max: 255 })
  );
  assert(errors.length === 0, errors.join(', '));
  assert(code.includes('Math.min(Math.max'));
  assert(code.includes('255'));
});

test('math.lerp 노드 컴파일', () => {
  const compiler = new GraphCompiler();
  const { code } = compiler.compile(
    buildGraph('stdlib:math.lerp', { a: 0, b: 100, t: 0.7 })
  );
  assert(code.includes('a + (b - a) * t'));
  assert(code.includes('0.7'));
});

test('string.template 노드 컴파일', () => {
  const compiler = new GraphCompiler();
  const { code } = compiler.compile(
    buildGraph('stdlib:string.template', { template: 'Hello {name}' })
  );
  assert(code.includes('replace'));
  assert(code.includes('Hello'));
});

test('array.chunk 노드 컴파일', () => {
  const compiler = new GraphCompiler();
  const { code } = compiler.compile(
    buildGraph('stdlib:array.chunk', { size: 4 })
  );
  assert(code.includes('out.push'));
  assert(code.includes('4'));
});

test('stdlib 코드가 script 블록 안에 포함', () => {
  const compiler = new GraphCompiler();
  const { code } = compiler.compile(buildGraph('stdlib:datetime.now'));
  // script { ... stdlib ... } 구조 확인
  const scriptStart = code.indexOf('script {');
  const scriptEnd   = code.indexOf('\n  }', scriptStart);
  const scriptBlock = code.slice(scriptStart, scriptEnd);
  assert(scriptBlock.includes('new Date()'));
});

test('stdlib 노드가 constNodes에서 제외됨 (중복 없음)', () => {
  const compiler = new GraphCompiler();
  const { code } = compiler.compile(
    buildGraph('stdlib:math.clamp', { min: 0, max: 100 })
  );
  // "Math.min(Math.max" 가 단 1회만 등장해야 함
  const count = (code.match(/Math\.min\(Math\.max/g) || []).length;
  assert(count === 1, `중복 발생: ${count}번`);
});

// ── 요약 ────────────────────────────────────────────────────
console.log(`\n${'─'.repeat(40)}`);
console.log(`Phase 15 테스트: ${pass} 통과 / ${fail} 실패 / 전체 ${pass + fail}`);
if (fail > 0) process.exit(1);

