/**
 * FreeWire Phase 15 — Plugin Bridge & StdLib 노드 통합 테스트
 * node src/test/test-phase15.js
 */
'use strict';

let pass = 0, fail = 0;

function test(label, fn) {
  try {
    fn();
    console.log(`  ✓ ${label}`);
    pass++;
  } catch (e) {
    console.error(`  ✗ ${label}: ${e.message}`);
    fail++;
  }
}

function assert(cond, msg = 'assertion failed') {
  if (!cond) throw new Error(msg);
}

// ── 모듈 로드 ────────────────────────────────────────────────
const { GraphCompiler }           = require('../compiler/graph-compiler');
const { Graph }                   = require('../core/graph');

// ────────────────────────────────────────────────────────────
// 모의 PluginBridge
// ────────────────────────────────────────────────────────────

class MockPluginBridge {
  constructor() {
    this._ready = true;
    this._nodeDefs = [
      {
        type: 'stdlib:datetime.now',
        label: 'DateTime Now',
        category: 'datetime',
        inputs: [],
        outputs: [{ name: 'timestamp', type: 'number' }],
        codeGen: (node) => 'const now = Date.now();'
      },
      {
        type: 'stdlib:math.clamp',
        label: 'Math Clamp',
        category: 'math',
        inputs: [
          { name: 'value', type: 'number' },
          { name: 'min', type: 'number' },
          { name: 'max', type: 'number' }
        ],
        outputs: [{ name: 'result', type: 'number' }],
        codeGen: (node) => 'function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }'
      },
      {
        type: 'stdlib:math.lerp',
        label: 'Math Lerp',
        category: 'math',
        inputs: [
          { name: 'a', type: 'number' },
          { name: 'b', type: 'number' },
          { name: 't', type: 'number' }
        ],
        outputs: [{ name: 'result', type: 'number' }],
        codeGen: (node) => 'function lerp(a, b, t) { return a + (b - a) * t; }'
      },
      {
        type: 'stdlib:string.template',
        label: 'String Template',
        category: 'string',
        inputs: [{ name: 'template', type: 'string' }],
        outputs: [{ name: 'result', type: 'string' }],
        codeGen: (node) => 'const template = (str) => str.replace(/\\${[^}]+}/g, "");'
      },
      {
        type: 'stdlib:string.truncate',
        label: 'String Truncate',
        category: 'string',
        inputs: [
          { name: 'text', type: 'string' },
          { name: 'len', type: 'number' }
        ],
        outputs: [{ name: 'result', type: 'string' }],
        codeGen: (node) => 'const truncate = (s, n) => s.slice(0, n);'
      },
      {
        type: 'stdlib:array.chunk',
        label: 'Array Chunk',
        category: 'array',
        inputs: [
          { name: 'array', type: 'any' },
          { name: 'size', type: 'number' }
        ],
        outputs: [{ name: 'chunks', type: 'any' }],
        codeGen: (node) => 'function chunk(arr, sz) { const out = []; for(let i=0; i<arr.length; i+=sz) out.push(arr.slice(i, i+sz)); return out; }'
      },
      {
        type: 'stdlib:array.groupBy',
        label: 'Array GroupBy',
        category: 'array',
        inputs: [
          { name: 'array', type: 'any' },
          { name: 'key', type: 'string' }
        ],
        outputs: [{ name: 'groups', type: 'object' }],
        codeGen: (node) => 'function groupBy(arr, k) { const result = {}; arr.forEach(x => { const g = x[k]; if(!result[g]) result[g] = []; result[g].push(x); }); return result; }'
      },
      {
        type: 'stdlib:json.parse',
        label: 'JSON Parse',
        category: 'json',
        inputs: [{ name: 'text', type: 'string' }],
        outputs: [{ name: 'object', type: 'any' }],
        codeGen: (node) => 'const parse = JSON.parse;'
      },
      {
        type: 'stdlib:json.stringify',
        label: 'JSON Stringify',
        category: 'json',
        inputs: [{ name: 'object', type: 'any' }],
        outputs: [{ name: 'text', type: 'string' }],
        codeGen: (node) => 'const stringify = JSON.stringify;'
      },
      {
        type: 'stdlib:http.fetch',
        label: 'HTTP Fetch',
        category: 'http',
        inputs: [{ name: 'url', type: 'string' }],
        outputs: [{ name: 'response', type: 'any' }],
        codeGen: (node) => 'async function httpFetch(url) { return await fetch(url); }'
      }
    ];
    this._codeGenMap = {};
    this._nodeDefs.forEach(def => {
      this._codeGenMap[def.type] = def.codeGen;
    });
  }

  get isReady() { return this._ready; }
  get nodeDefs() { return this._nodeDefs; }

  isStdlibNode(node) {
    return typeof node?.stdlibFn === 'string' ||
           (typeof node?.type === 'string' && node.type.startsWith('stdlib:'));
  }

  codeGenNode(node) {
    const type = node.stdlibFn ? `stdlib:${node.stdlibFn}` : node.type;
    const codeGen = this._codeGenMap[type];
    if (!codeGen) return `/* stdlib codeGen 없음: ${type} */`;
    return codeGen(node);
  }

  getPaletteCategory() {
    return {
      label: 'Standard Library',
      color: '#4CAF50',
      icon: 'library',
      subtypes: [
        { id: 'stdlib:datetime.now', label: 'DateTime Now', color: '#FF9800' },
        { id: 'stdlib:math.clamp', label: 'Math Clamp', color: '#2196F3' },
        { id: 'stdlib:array.chunk', label: 'Array Chunk', color: '#9C27B0' }
      ]
    };
  }

  createNode(type, id, opts = {}) {
    const def = this._nodeDefs.find(d => d.type === type);
    if (!def) throw new Error(`stdlib node not found: ${type}`);
    return {
      id,
      type,
      label: def.label,
      category: def.category,
      stdlibFn: type.replace('stdlib:', ''),
      dataType: 'stdlib',
      ...opts
    };
  }
}

const mockBridge = new MockPluginBridge();

// ────────────────────────────────────────────────────────────
// 테스트 1: MockPluginBridge 검증
// ────────────────────────────────────────────────────────────

console.log('\n[MockPluginBridge / 초기화]');

test('isReady = true', () => {
  assert(mockBridge.isReady === true);
});

test('nodeDefs.length === 10', () => {
  assert(mockBridge.nodeDefs.length === 10);
});

test('nodeDefs[0] = stdlib:datetime.now', () => {
  const def = mockBridge.nodeDefs[0];
  assert(def.type === 'stdlib:datetime.now');
  assert(def.label === 'DateTime Now');
  assert(typeof def.codeGen === 'function');
});

console.log('\n[MockPluginBridge / isStdlibNode]');

test('isStdlibNode — stdlibFn 있으면 true', () => {
  const node = { id: 'n1', stdlibFn: 'math.clamp' };
  assert(mockBridge.isStdlibNode(node) === true);
});

test('isStdlibNode — type이 stdlib:로 시작하면 true', () => {
  const node = { id: 'n1', type: 'stdlib:math.clamp' };
  assert(mockBridge.isStdlibNode(node) === true);
});

test('isStdlibNode — 일반 노드는 false', () => {
  const node = { id: 'n1', type: 'data' };
  assert(mockBridge.isStdlibNode(node) === false);
});

console.log('\n[MockPluginBridge / codeGenNode]');

test('codeGenNode — math.clamp 생성', () => {
  const node = { type: 'stdlib:math.clamp' };
  const code = mockBridge.codeGenNode(node);
  assert(code.includes('clamp'));
  assert(code.includes('Math.max'));
});

test('codeGenNode — datetime.now 생성', () => {
  const node = { type: 'stdlib:datetime.now' };
  const code = mockBridge.codeGenNode(node);
  assert(code.includes('Date.now'));
});

test('codeGenNode — stdlibFn 기준 동작', () => {
  const node = { stdlibFn: 'array.chunk' };
  const code = mockBridge.codeGenNode(node);
  assert(code.includes('chunk'));
});

console.log('\n[MockPluginBridge / getPaletteCategory]');

test('getPaletteCategory — 반환 구조', () => {
  const cat = mockBridge.getPaletteCategory();
  assert(cat.label === 'Standard Library');
  assert(cat.color === '#4CAF50');
  assert(Array.isArray(cat.subtypes));
});

test('getPaletteCategory — subtypes 포함', () => {
  const cat = mockBridge.getPaletteCategory();
  assert(cat.subtypes.length > 0);
  assert(cat.subtypes[0].id === 'stdlib:datetime.now');
});

console.log('\n[MockPluginBridge / createNode]');

test('createNode — datetime.now', () => {
  const node = mockBridge.createNode('stdlib:datetime.now', 'n1');
  assert(node.id === 'n1');
  assert(node.type === 'stdlib:datetime.now');
  assert(node.stdlibFn === 'datetime.now');
});

test('createNode — math.clamp with opts', () => {
  const node = mockBridge.createNode('stdlib:math.clamp', 'n2', { min: 0, max: 100 });
  assert(node.min === 0);
  assert(node.max === 100);
  assert(node.label === 'Math Clamp');
});

test('createNode — 없는 타입 throw', () => {
  try {
    mockBridge.createNode('stdlib:nonexistent', 'n999');
    throw new Error('should have thrown');
  } catch (e) {
    assert(e.message.includes('not found'));
  }
});

// ────────────────────────────────────────────────────────────
// 테스트 2: Graph + GraphCompiler (stdlib 노드 필터링)
// ────────────────────────────────────────────────────────────

console.log('\n[GraphCompiler / stdlib 노드 필터링]');

test('Graph.topologicalSort — 정상 동작', () => {
  const graph = new Graph();
  graph.addNode({ id: 'n1', type: 'data', dataType: 'props' });
  graph.addNode({ id: 'n2', type: 'data', dataType: 'state' });
  const sorted = graph.topologicalSort();
  assert(sorted.length === 2);
});

test('stdlib 노드 필터링 로직 — isStdlibNode 사용', () => {
  const graph = new Graph();
  graph.addNode({ id: 'n1', type: 'data', dataType: 'props' });
  graph.addNode({ id: 'n2', type: 'data', dataType: 'state' });
  graph.addNode({ id: 'n3', type: 'data', dataType: 'other', stdlibFn: 'math.clamp' });

  const sorted = graph.topologicalSort();
  const stdlibNodes = sorted.filter(n => mockBridge.isStdlibNode(n));

  assert(stdlibNodes.length === 1);
  assert(stdlibNodes[0].id === 'n3');
});

test('constNodes에서 stdlib 노드 제외', () => {
  const graph = new Graph();
  graph.addNode({ id: 'n1', type: 'data', dataType: 'const', value: 10 });
  graph.addNode({ id: 'n2', type: 'data', dataType: 'const', stdlibFn: 'math.add' });

  const sorted = graph.topologicalSort();
  const constNodes = sorted.filter(n =>
    n.type === 'data' &&
    !['props', 'state'].includes(n.dataType) &&
    !mockBridge.isStdlibNode(n)
  );

  assert(constNodes.length === 1);
  assert(constNodes[0].id === 'n1');
});

// ────────────────────────────────────────────────────────────
// 테스트 3: GraphCompiler (stdlib 코드 생성)
// ────────────────────────────────────────────────────────────

console.log('\n[GraphCompiler / stdlib 코드 생성]');

const compiler = new GraphCompiler();

test('compile() — stdlib 노드 포함된 그래프', () => {
  const graph = new Graph();
  graph.addNode({
    id: 'n1',
    type: 'component',
    name: 'TestComp'
  });
  graph.addNode({
    id: 'n2',
    type: 'data',
    dataType: 'state',
    name: 'count',
    value: 0
  });
  graph.addNode({
    id: 'n3',
    type: 'data',
    dataType: 'other',
    stdlibFn: 'math.clamp',
    name: 'clampFn'
  });

  const result = compiler.compile(graph);
  assert(typeof result === 'string');
  assert(result.includes('count') || result.includes('<script'));
});

test('stdlib 코드 생성 시 codeGenNode() 사용', () => {
  const node = mockBridge.createNode('stdlib:array.chunk', 'n1');
  const code = mockBridge.codeGenNode(node);
  assert(code.length > 0);
  assert(!code.includes('undefined'));
});

// ────────────────────────────────────────────────────────────
// 최종 결과
// ────────────────────────────────────────────────────────────

console.log('\n────────────────────────────────────────────────────────');
console.log(`Phase 15 테스트: ${pass} 통과 / ${fail} 실패 / 전체 ${pass + fail}`);
console.log('────────────────────────────────────────────────────────');

if (fail === 0) {
  console.log('✓ 모든 테스트 통과!');
  process.exit(0);
} else {
  console.log(`✗ ${fail}개 실패`);
  process.exit(1);
}

