    17→  AI:        'ai',
    18→};
    19→
    20→/** 포트 타입 호환성 매트릭스 */
    21→const PORT_COMPAT = {
    22→  component: ['component', 'any'],
    23→  data:      ['data', 'any'],
    24→  logic:     ['logic', 'any'],
    25→  event:     ['event', 'any'],
    26→  any:       ['component', 'data', 'logic', 'event', 'any'],
    27→};
    28→
    29→/**
    30→ * 두 포트가 연결 가능한지 검사
    31→ * @param {string} outputType - 출력 포트 타입
    32→ * @param {string} inputType  - 입력 포트 타입
    33→ * @returns {boolean}
    34→ */
    35→function isCompatible(outputType, inputType) {
    36→  const allowed = PORT_COMPAT[outputType] || [];
    37→  return allowed.includes(inputType);
    38→}
    39→
    40→/**
    41→ * 노드 JSON 기본 유효성 검사
    42→ * @param {object} node
    43→ * @returns {{ valid: boolean, errors: string[] }}
    44→ */
    45→function validateNode(node) {
    46→  const errors = [];
    47→
    48→  if (!node.id || typeof node.id !== 'string')
    49→    errors.push('id: 문자열 필수');
    50→
    51→  if (!node.type || !Object.values(NODE_TYPES).includes(node.type))
    52→    errors.push(`type: ${Object.values(NODE_TYPES).join('|')} 중 하나여야 함`);
    53→
    54→  if (!Array.isArray(node.inputs))
    55→    errors.push('inputs: 배열 필수');
    56→
    57→  if (!Array.isArray(node.outputs))
